    handlers = {}

    # First, look for an explicit registry on the class if it exists
    registry = getattr(cls, "_protocol_handlers", None)
    if isinstance(registry, dict):
        handlers.update({tuple(k): v for k, v in registry.items() if isinstance(k, tuple)})

    # Helper to extract candidate object when attribute might be wrapped (staticmethod, classmethod)
    def _candidate(attr):
        return attr.__func__ if isinstance(attr, (staticmethod, classmethod)) else attr

    # Inspect the class dictionary for attributes that carry a protocol version marker
    for attr_value in cls.__dict__.values():
        cand = _candidate(attr_value)
        if hasattr(cand, "_protocol_version"):
