def unit_of_work(metadata=None, timeout=None):
    """
    This function is a decorator for transaction functions that allows extra control over how the transaction is carried out.
    """
    def decorator(func):
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            import os
            try:
                # Resolve Neo4j URI; allow overriding via keyword argument 'uri'
                uri = kwargs.pop('uri', os.getenv('NEO4J_URI', 'bolt://localhost:7687'))
                from neo4j import GraphDatabase
                driver = GraphDatabase.driver(uri)
                try:
                    # Validate timeout
                    if timeout is not None:
                        if not isinstance(timeout, (int, float)):
                            raise TypeError("timeout must be a number or None")
                        if timeout < 0:
                            raise ValueError("timeout cannot be negative")
                        # Neo4j timeout is specified in milliseconds
                        timeout_ms = int(timeout * 1000)
                    else:
                        timeout_ms = None

                    tx_config = {}
                    if timeout_ms is not None:
                        # Zero timeout means unlimited duration, so omit it
                        if timeout_ms != 0:
                            tx_config['timeout'] = timeout_ms
                    if metadata:
                        tx_config['metadata'] = metadata

                    with driver.session() as session:
                        return session.write_transaction(func, *args, **kwargs, transaction_config=tx_config)
                finally:
                    driver.close()
            except Exception as e:
                # Re-raise with a clear message to aid troubleshooting
                raise RuntimeError(f"unit_of_work failed: {e}") from e
        return wrapper
    return decorator

