def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Ensure input is string
    if not isinstance(code, str):
        raise TypeError("code must be a string")

    import re

    # Default options to set
    options_to_set = {
        "max.print": "1e6",
        "encoding": "\"UTF-8\"",
        "stringsAsFactors": "FALSE"
    }

    # If code is empty, just return options block
    if not code.strip():
        return "\n".join(f"options({opt} = {val})" for opt, val in options_to_set.items())

    lines = code.splitlines()
    insert_idx = 0

    # Preserve a shebang or initial comments at the top
    if lines and lines[0].startswith("#!"):  # shebang line
        insert_idx = 1
        # also skip any following comment lines that start with '#'
        while insert_idx < len(lines) and lines[insert_idx].startswith("#"):
            insert_idx += 1

    # Determine which options are missing
    missing = []
    for opt, val in options_to_set.items():
        pattern = rf"^\s*options\s*\(\s*{opt}\s*="
        if not re.search(pattern, code, flags=re.MULTILINE):
            missing.append(f"options({opt} = {val})")

    if missing:
        # Insert missing options after any shebang/comments
        for i, opt_line in enumerate(missing, start=insert_idx):
            lines.insert(i, opt_line)
        # Ensure one blank line before code (if inserted options added)
        if insert_idx == 0 and missing:
            # Already inserted at top; we might want a new line for readability
            lines.insert(0, "")

    return "\n".join(lines) + ("\n" if not code.endswith("\n") else "")

