    only be configured via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError("code must be a string")
    # Define common R options that are often needed
    options_setup = [
        "options(stringsAsFactors = FALSE)",
        "options(digits = 3)",
        "options(warn = 2)",
    ]
    # Split the existing code into lines
    lines = code.splitlines()
    # Detect which options are already present
    already_set = {opt for opt in options_setup if any(opt.split()[0] in line for line in lines)}
    # Prepare header lines for missing options
    missing_opts = [opt for opt in options_setup if opt not in already_set]
    if missing_opts:
        header_lines = missing_opts + [""]
    else:
        header_lines = []
    # If the code is empty, just return the header lines
    if not lines:
        return "\n".join(header_lines).rstrip()
    return "\n".join(header_lines + lines).rstrip()

