def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not s:
        return (0,)
    # Strip leading 'v' or 'V'
    s = s.lstrip('vV')
    parts = s.split('.')
    ver_nums = []
    for part in parts:
        # Extract leading digits only
        match = re.match(r'(\d+)', part)
        if match:
            ver_nums.append(int(match.group(1)))
        else:
            # Non-numeric part encountered; stop parsing further
            break
    return tuple(ver_nums)

