    """poor man's version comparison"""

    # Trim whitespace
    s = s.strip()
    if not s:
        return ()
    parts = s.split('.')
    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            raise ValueError(f"Invalid version component '{part}' in '{s}'")
    return tuple(nums)

