@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        # Helper to shorten file paths
        def _shorten_path(path, max_parts):
            if not path:
                return ''
            # Normalize path separators
            parts = path.replace('\\', '/').split('/')
            if len(parts) > max_parts:
                return '/'.join(parts[-max_parts:])
            return path

        out_lines = []

        try:
            # Basic exception description
            if isinstance(e, BaseException):
                # Exception with message
                out_lines.append(f"{e.__class__.__name__}: {e}")
            else:
                # Non-exception objects
                out_lines.append(f"{type(e).__name__}: {e}")
        except Exception:
            try:
                out_lines.append(str(e))
            except Exception:
                out_lines.append("<unprintable exception>")

        # Attempt to process traceback
        tb = None
        try:
            # Prefer attribute on the exception
            tb = getattr(e, "__traceback__", None)
        except Exception:
            pass

        # If not found, try sys.exc_info()
        if tb is None:
            try:
                import sys
                tb = sys.exc_info()[2]
            except Exception:
                tb = None

        # If we have a traceback, build a formatted stack
        if tb is not None:
            frames = []
            count = 0
            # Walk through the traceback chain
            while tb and count < max_level:
                try:
                    frame = tb.tb_frame
                    lineno = tb.tb_lineno
                    code = frame.f_code  # type: ignore
                    filename = getattr(code, "co_filename", "")
                    name = getattr(code, "co_name", "")
                    short_path = _shorten_path(filename, max_path_level)
                    frames.append((short_path, lineno, name))
                except Exception:
                    pass
                tb = tb.tb_next
                count += 1

            if frames:
                # Add a traceback header
                out_lines.append("Traceback (most recent call last):")
                for fp, ln, nm in frames:
                    out_lines.append(f"  File '{fp}', line {ln}, in {nm}")

        # Join into single string
        return "\n".join(out_lines)

