def _reset_logging(cls):
    """Reset"""
    try:
        # Get the root logger
        root_logger = logging.getLogger()
        # Remove and close all existing handlers
        for handler in list(root_logger.handlers):
            try:
                root_logger.removeHandler(handler)
                handler.close()
            except Exception:
                # Ignore errors during handler cleanup
                pass
        # Reset logger level to WARNING (default)
        root_logger.setLevel(logging.WARNING)
        # If no handlers left, add a default StreamHandler
        if not root_logger.handlers:
            stream_handler = logging.StreamHandler()
            stream_handler.setFormatter(
                logging.Formatter('%(levelname)s:%(name)s:%(message)s')
            )
            root_logger.addHandler(stream_handler)
    except Exception as exc:
        # If something goes wrong, at least log the exception to stderr
        try:
            sys.stderr.write(f"Failed to reset logging: {exc}\n")
        except Exception:
            pass

