def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []
    if not isinstance(classes, (list, tuple, set)):
        try:
            iter(classes)
        except TypeError:
            raise TypeError("classes must be an iterable of types")
    seen = set()
    result = []
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"{cls!r} is not a class type")
        if cls in seen:
            continue
        # Skip if already covered by an existing base
        if any(issubclass(cls, existing) for existing in result):
            continue
        # Remove any existing bases that are subclasses of the new class
        result = [e for e in result if not issubclass(e, cls)]
        result.append(cls)
        seen.add(cls)
    return result

