def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import sys
        import os
    except Exception:
        # If imports fail (unlikely), we err on the side of caution and disallow C
        return False

    # Detect PyPy implementation; if we're on PyPy, avoid C extensions
    try:
        impl_name = sys.implementation.name
    except AttributeError:
        import platform
        impl_name = platform.python_implementation()
    if impl_name.lower().startswith('pypy'):
        return False

    # Respect explicit environment variable to force pure Python
    pure_python = os.environ.get('PURE_PYTHON')
    if pure_python is not None:
        return pure_python.lower() not in ('1', 'true', 'yes')

    # Default: attempt C optimization
    return True

