def to_csv(self, separator=",", header=None):
    """
    .. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
    Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Prepare output lines
    lines = []

    if header is not None:
        # Ensure a single newline after the header
        lines.append(str(header).rstrip("\n") + "\n")

    # Determine an iterable over points
    try:
        # Prioritize a method if present
        if callable(getattr(self, "points", None)):
            points_iter = self.points()
        else:
            points_iter = getattr(self, "points", [])
            if not isinstance(points_iter, (list, tuple, set)):
                # Try generic iteration
                points_iter = list(points_iter)
    except Exception:
        # Fall back to empty iteration
        points_iter = []

    for point in points_iter:
        try:
            # Default expectations:
            # point may be (coord, value) or just value with implicit coords
            if isinstance(point, tuple) or isinstance(point, list):
                if len(point) == 2:
                    coord, value = point
                else:
                    # Interpret last element as value, rest as coordinates
                    coord = point[:-1]
                    value = point[-1]
            else:
                # Not a tuple/list: treat as value with no coordinates
                coord = ()
                value = point

            # Convert coordinates to string list
            if isinstance(coord, (list, tuple, set)):
                coord_strs = [str(c) for c in coord]
            else:
                coord_strs = [str(coord)]

            # Convert value to string(s)
            if isinstance(value, (list, tuple, set)):
                value_strs = [str(v) for v in value]
            else:
                value_strs = [str(value)]

            lines.append(separator.join(coord_strs + value_strs) + "\n")
        except Exception:
            # Skip problematic points
            continue

    return "".join(lines)

