    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to NumPy arrays
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise ValueError("bins and edges must be array‑like and numeric") from exc

    # Basic shape checks
    if bins_arr.ndim != 1:
        raise ValueError("bins must be a 1‑D array or sequence")
    if edges_arr.ndim != 1:
        raise ValueError("edges must be a 1‑D array or sequence")
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError("Number of bin edges must be one more than number of bins")

    # Compute bin widths
    widths = np.diff(edges_arr)

    # Integrate: sum of bin value times bin width
    return np.sum(bins_arr * widths)

