def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Empty path is invalid
    if not path:
        return False

    try:
        # Resolve path-like objects to a string
        p = os.fspath(path)
    except Exception:
        # Non-pathlike values are invalid
        return False

    # Path must exist and be a directory
    if not os.path.isdir(p):
        return False

    # Basic OCFL object structure checks
    # The minimum required folder for an OCFL object is the ".ocfl" directory
    # If it is a pyfs root, it should contain at least a "objects" directory
    ocfl_dir = os.path.join(p, ".ocfl")
    objects_dir = os.path.join(p, "objects")

    # Determine if it is an object root or a pyfs root by presence of these dirs
    if os.path.isdir(ocfl_dir):
        root_type = "object"
    elif os.path.isdir(objects_dir):
        root_type = "pyfs"
    else:
        # Neither valid root type
        return False

    # Validate required files inside the object root
    if root_type == "object":
        config = os.path.join(p, ".ocfl", "config.json")
        if not os.path.isfile(config):
            # Config file is mandatory for an OCFL object
            return False
        # Optional manifest; permit warnings if missing
        manifest = os.path.join(p, ".ocfl", "manifest")
        if not os.path.isdir(manifest):
            # Warn, but don't fail
            try:
                import warnings
                warnings.warn(f"Expected manifest directory missing at {manifest}")
            except Exception:
                pass
    else:  # pyfs root
        # Ensure at least one object directory exists
        try:
            subdirs = [
                d for d in os.listdir(objects_dir)
                if os.path.isdir(os.path.join(objects_dir, d))
            ]
        except Exception:
            return False
        if not subdirs:
            # No objects found
            return False

    # All checks passed; return True
    return True

