    """
    try:
        if not path:
            return False

        # If a filesystem-like object is provided, just check if it has a root directory
        if hasattr(path, "exists") and hasattr(path, "getinfo"):
            try:
                # Treat the root as valid if it has a directory entry
                return any(
                    info.is_dir
                    for info in path.listdir(".")
                )
            except Exception:
                return False

        # Assume a string or pathlib Path
        import os

        # Resolve the path to an absolute string
        path_str = str(path)

        if not os.path.isdir(path_str):
