        ocfl_root = os.path.join(path_str, ".ocfl_root")
        if os.path.isdir(ocfl_root):
            # Check for a manifest file inside the OCFL root
            manifest_path = os.path.join(ocfl_root, "manifest")
            return os.path.exists(manifest_path)

        # If ".ocfl_root" is not directly inside, search up the directory tree
        current = os.path.abspath(path_str)
        while True:
            candidate = os.path.join(current, ".ocfl_root")
            if os.path.isdir(candidate):
                manifest_path = os.path.join(candidate, "manifest")
                return os.path.exists(manifest_path)
            parent = os.path.dirname(current)
            if parent == current:
                break
            current = parent

