def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure the prior object is of the same type
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__} (got {type(prior).__name__})")

    # Retrieve common attributes safely; if any are missing, raise a clear error
    try:
        self_species = self.species
        self_params = self.parameters
        self_stoich = self.stoichiometry_matrix
        self_props = self.propensities
    except AttributeError as exc:
        raise AttributeError(f"Current inventory missing required attribute: {exc}") from exc

    try:
        prior_species = prior.species
        prior_params = prior.parameters
        prior_stoich = prior.stoichiometry_matrix
        prior_props = prior.propensities
    except AttributeError as exc:
        raise AttributeError(f"Prior inventory missing required attribute: {exc}") from exc

    # 1. Species: current inventory should contain all species from prior
    missing_species = [s for s in prior_species if s not in self_species]
    if missing_species:
        raise ValueError(f"Current inventory missing species from prior: {missing_species}")

    # 2. Parameters: current inventory should contain all parameters from prior
    missing_params = [p for p in prior_params if p not in self_params]
    if missing_params:
        raise ValueError(f"Current inventory missing parameters from prior: {missing_params}")

    # 3. Verify stoichiometry matrix shapes match expectations
    def check_shape(name, matrix, expected_rows, expected_cols):
        if matrix.shape != (expected_rows, expected_cols):
            raise ValueError(f"{name}. shape {matrix.shape} does not match expected "
                             f"({expected_rows}x{expected_cols})")

    check_shape(f"self_stoichiometry_matrix", self_stoich, len(self_species), len(self_props))
    check_shape(f"prior_stoichiometry_matrix", prior_stoich, len(prior_species), len(prior_props))

    # 4. Verify that the sub‑matrix of the current inventory that corresponds to the
    #    prior inventory matches exactly.
    spec_index_self = {s: i for i, s in enumerate(self_species)}
    try:
        prop_index_self = {p: i for i, p in enumerate(self_props)}
    except TypeError:
        # If propensities are not indexable (e.g., plain numbers), fall back
        prop_index_self = {p: idx for idx, p in enumerate(self_props)}

    for i_prior, species in enumerate(prior_species):
        i_self = spec_index_self[species]
        for j_prior, propensity in enumerate(prior_props):
            j_self = prop_index_self.get(propensity, j_prior)  # fall back to same index
            val_prior = prior_stoich[i_prior, j_prior]
            val_self = self_stoich[i_self, j_self]
            if val_prior != val_self:
                raise ValueError(f"Stoichiometry mismatch for species '{species}' "
                                 f"and propensity '{propensity}': prior={val_prior} vs current={val_self}")

    # If all checks pass, the prior is considered a valid prior version.
    return True

