                            continue
                else:
                    # direct collection
                    try:
                        mapping.setdefault(logical_path, set()).update(files)
                    except Exception:
                        try:
                            mapping.setdefault(logical_path, set()).add(files)
                        except Exception:
                            continue
        # Case 2: a list of entry dictionaries
        elif isinstance(data, list):
            for entry in data:
                try:
                    if isinstance(entry, dict):
                        logical_path = entry.get("logical_path") or entry.get("lp")
                        content_file = entry.get("content_file") or entry.get("file")
                        if logical_path and content_file:
                            mapping.setdefault(logical_path, set()).add(content_file)
                except Exception:
                    continue
    except Exception:
        pass
    return mapping

