def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    import xml.etree.ElementTree as ET
    from collections import defaultdict

    def _elem_to_dict(elem):
        """
        Recursively convert an ElementTree element to a dictionary.
        """
        d = {}
        if elem.attrib:
            d.update({f"@{k}": v for k, v in elem.attrib.items()})
        children = list(elem)
        if children:
            child_dict = defaultdict(list)
            for child in children:
                child_dict[child.tag].append(_elem_to_dict(child))
            # Simplify lists that contain only one element
            for key, val in list(child_dict.items()):
                if len(val) == 1:
                    child_dict[key] = val[0]
            d.update(child_dict)
        if elem.text and elem.text.strip():
            d["#text"] = elem.text.strip()
        return d

    if not folder:
        raise ValueError("folder path must be provided")

    data_by_basename = defaultdict(list)

    if not os.path.isdir(folder):
        raise FileNotFoundError(f"The specified folder does not exist: {folder}")

    try:
        for entry in os.listdir(folder):
            full_path = os.path.join(folder, entry)
            if not os.path.isfile(full_path):
                continue
            if not entry.lower().endswith(".xml"):
                continue
            basename = os.path.splitext(entry)[0]
            try:
                tree = ET.parse(full_path)
                root = tree.getroot()
                pkg_dict = _elem_to_dict(root)
                data_by_basename[basename].append(pkg_dict)
            except ET.ParseError:
                # Skip files that cannot be parsed as XML
                continue
    except Exception as exc:
        raise RuntimeError(f"Error exploring folder '{folder}': {exc}") from exc

    return dict(data_by_basename)

def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    # Ensure the folder exists
    if not os.path.isdir(folder):
        return {}

    # List all files in the specified folder (non-recursive)
    files = [f for f in os.listdir(folder) if os.path.isfile(os.path.join(folder, f))]

    # Group files by their stem (basename without extension)
    grouped_files = {}
    for filename in files:
        stem, _ = os.path.splitext(filename)
        grouped_files.setdefault(stem, []).append(filename)

    result = {}

    for stem, file_list in grouped_files.items():
        # Only consider groups that have an XML file
        if not any(f.lower().endswith('.xml') for f in file_list):
            continue

        group_data = []
        for fname in file_list:
            full_path = os.path.join(folder, fname)
            try:
                with open(full_path, 'r', encoding='utf-8') as fp:
                    content = fp.read()
            except Exception:
                content = None
            group_data.append({
                'name': fname,
                'full_path': full_path,
                'content': content
            })

        result[stem] = group_data

    return result

