    dict
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder not found: {folder}")

    # Collect all files by basename (without extension)
    files_by_base = {}
    for root, _, files in os.walk(folder):
        for filename in files:
            base, _ext = os.path.splitext(filename)
            full_path = os.path.join(root, filename)
            files_by_base.setdefault(base, []).append(full_path)

    # Only keep groups that have at least one XML file
    packages = {}
    for base, paths in files_by_base.items():
        if any(p.lower().endswith('.xml') for p in paths):
            packages[base] = paths

    return packages

