def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path.

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path

    Returns
    -------
    dict
    """
    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            xml_bases = set()

            # Identify all XML basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_bases.add(base)

            # No XML files found; return empty dict
            if not xml_bases:
                return {}

            data = {}
            # Group all files that share an XML basename
            for info in zf.infolist():
                if info.is_dir():
                    continue
                base = os.path.splitext(os.path.basename(info.filename))[0]
                if base in xml_bases:
                    if base not in data:
                        data[base] = {}
                    data[base][info.filename] = zf.read(info.filename)

            return data

    except (FileNotFoundError, zipfile.BadZipFile) as exc:
        raise ValueError(f"Unable to read zip file {zip_path}: {exc}") from exc

