    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError("zip_path must be a string")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"Zip file {zip_path} does not exist")

    # Mapping from basename (without extension) to the XML path
    xml_basenames = {}

    # First pass: collect all XML files and their basenames
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                filename = zinfo.filename
                if filename.lower().endswith('.xml'):
                    base = os.path.splitext(os.path.basename(filename))[0]
                    xml_basenames[base] = filename
    except Exception as e:
        raise RuntimeError(f"Failed to read zip file {zip_path}: {e}")

    # If no XML files found, simply return an empty dict
    if not xml_basenames:
        return {}

    # Second pass: group all files that share the same XML basename
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zin:
            for zinfo in zin.infolist():
                if zinfo.is_dir():
                    continue
                filename = zinfo.filename
                # Determine the basename without extension
                base = os.path.splitext(os.path.basename(filename))[0]
                if base in xml_basenames:
                    package_key = base
                    if package_key not in result:
                        result[package_key] = {}
                    # Read the file content
                    content = zin.read(zinfo)
                    # Use the relative path inside the zip as the key
                    result[package_key][filename] = content
    except Exception as e:
        raise RuntimeError(f"Error while grouping files in {zip_path}: {e}")

    return result

