def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    def _pretty(obj, level):
        ind = '    ' * level
        if isinstance(obj, dict):
            if not obj:
                return "{}"
            items = []
            for k, v in sorted(obj.items(), key=str):
                items.append(f"{ind}    {repr(k)}: {_pretty(v, level + 1)}")
            return "{\n" + ",\n".join(items) + f"\n{ind}}}"
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                return f"{type(obj).__name__}()"
            items = []
            for v in obj:
                items.append(f"{ind}    {_pretty(v, level + 1)}")
            closing = "]" if isinstance(obj, list) else ")" if isinstance(obj, tuple) else "}"
            opening = "[" if isinstance(obj, list) else "(" if isinstance(obj, tuple) else "{"
            return f"{opening}\n" + ",\n".join(items) + f"\n{ind}{closing}"
        if hasattr(obj, "__dict__") and obj is not self:
            return _pretty(obj.__dict__, level)
        if hasattr(obj, "__slots__") and obj is not self:
            slot_dict = {slot: getattr(obj, slot) for slot in obj.__slots__}
            return _pretty(slot_dict, level)
        return repr(obj)
    result = _pretty(self, indent)
    if debug:
        result += f"\n# type: {type(self).__name__}"
    return result

try:
        import pprint
        pretty_str = pprint.pformat(self, indent=indent, width=80, depth=None)
    except Exception:
        pretty_str = f"<unrepresentable object {repr(self)}>"
    if debug:
        header = f"<{self.__class__.__name__} at {hex(id(self))}>"
        pretty_str = header + "\n" + pretty_str
    return pretty_str

