def render(pieces, style):
    """Render the given version pieces into the requested style.

    Parameters
    ----------
    pieces : list | tuple | dict | str
        The version components.  If a list/tuple, the components are
        taken in order.  If a dict, the standard keys ``major``, ``minor``,
        ``patch``, ``build`` and ``prerelease`` are looked up (any
        missing keys are treated as ``None``).  If a string, it is
        returned unchanged (unless a style that demands conversion is
        specified).

    style : str or None
        One of ``'string'`` (default), ``'tuple'``, ``'semantic'`` or
        ``'short'``.  ``'string'`` returns a dotted string,
        ``'tuple'`` returns a tuple of integers, ``'semantic'`` prepends a
        ``'v'`` to the dotted string, and ``'short'`` uses only the
        first two components.

    Returns
    -------
    str | tuple
        The rendered version.

    Raises
    ------
    ValueError
        If the input type is unsupported or if an unknown style is
        requested.
    """
    if style is None:
        style = 'string'

    # Normalize pieces into a list of components in order
    if isinstance(pieces, dict):
        comp_order = ['major', 'minor', 'patch', 'build', 'prerelease']
        comp = [pieces.get(k) for k in comp_order]
    elif isinstance(pieces, (list, tuple)):
        comp = list(pieces)
    elif isinstance(pieces, str):
        # If a string and style is only string or semantic, return it.
        if style in ('string', 'semantic'):
            return pieces
        else:
            # Attempt to parse the string into components
            try:
                comp = [int(p) for p in pieces.split('.')]
            except ValueError:
                # cannot parse into ints; use the string as a single component
                comp = [pieces]
    else:
        raise ValueError('Unsupported type for pieces: %r' % type(pieces))

    # Helper to clean components (remove None)
    cleaned = [c for c in comp if c is not None]

    if not cleaned:
        return '' if style in ('string', 'semantic', 'short') else tuple()

    # Build base dotted string
    dotted = '.'.join(str(c) for c in cleaned)

    if style == 'string':
        return dotted
    elif style == 'semantic':
        # Add leading 'v' but leave the string unchanged if already present
        return 'v%s' % dotted if not dotted.startswith('v') else dotted
    elif style == 'short':
        # Only first two parts
        short_parts = cleaned[:2]
        return '.'.join(str(c) for c in short_parts)
    elif style == 'tuple':
        try:
            return tuple(int(c) for c in cleaned)
        except ValueError as exc:
            raise ValueError('Cannot convert components to int for tuple style') from exc
    else:
        raise ValueError('Unknown style: %r' % style)

