def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of version directory names")
    if not version_dirs:
        return self

    # Inventory file name assumed to be 'inventory.json' by default; allow override
    inventory_filename = getattr(self, "inventory_filename", "inventory.json")

    root_inventory = None
    differences = {}  # key: file path, value: dict of version -> digest

    for idx, version_dir in enumerate(version_dirs, start=1):
        if not os.path.isdir(version_dir):
            raise FileNotFoundError(f"Version directory '{version_dir}' does not exist")

        inv_path = os.path.join(version_dir, inventory_filename)
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in '{version_dir}': {inv_path}")

        # Load inventory; favour JSON but also support simple key->digest lines
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                try:
                    inventory = json.load(f)
                except json.JSONDecodeError:
                    # fallback: simple line format `path digest`
                    inventory = {}
                    for line in f:
                        line = line.strip()
                        if not line or line.startswith("#"):
                            continue
                        parts = line.split()
                        if len(parts) < 2:
                            raise ValueError(f"Invalid inventory line in {inv_path}: {line!r}")
                        inventory[parts[0]] = parts[1]
        except OSError as exc:
            raise OSError(f"Could not read inventory file '{inv_path}': {exc}") from exc

        if idx == 1:
            root_inventory = inventory
            continue

        # Compare with root inventory
        for path, root_digest in root_inventory.items():
            current_digest = inventory.get(path)
            if current_digest is None:
                # File missing in this version
                differences.setdefault(path, {})[idx] = f"missing (root: {root_digest})"
            elif current_digest != root_digest:
                differences.setdefault(path, {})[idx] = f"{root_digest} -> {current_digest}"
        # Detect new files added in this version
        for path, cur_digest in inventory.items():
            if path not in root_inventory:
                differences.setdefault(path, {})[idx] = f"new ({cur_digest})"

    # Store resulting differences for later validation steps
    setattr(self, "_inventory_differences", differences)
    return self

