def parse_arguments(*arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a Namespace instance (the result of ArgumentParser.parse_args()).
    '''
    import argparse

    # Create a parser with a generic description
    parser = argparse.ArgumentParser(
        description='Parse command-line arguments for this script.'
    )

    # Example arguments; modify these as needed for the script's actual options.
    parser.add_argument(
        '-f', '--file', metavar='FILE', type=str, required=False,
        help='Path to the input file.'
    )
    parser.add_argument(
        '-v', '--verbose', action='store_true',
        help='Increase output verbosity.'
    )
    parser.add_argument(
        '-o', '--output', metavar='OUT', type=str, required=False,
        help='Path to write the output.'
    )

    # Flatten arguments if a single iterable was provided
    if len(arguments) == 1 and isinstance(arguments[0], (list, tuple)):
        arglist = arguments[0]
    else:
        arglist = arguments

    # Ensure all arguments are strings; otherwise argparse will raise an error
    if arglist and not all(isinstance(arg, str) for arg in arglist):
        raise TypeError("All command-line arguments must be strings.")

    # Parse and return the namespace
    if arglist:
        return parser.parse_args(arglist)
    else:
        # If no arguments were passed to the function, parse sys.argv
        return parser.parse_args()

