def parse_arguments(*unparsed_arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    parser = argparse.ArgumentParser()
    # Create a subparsers container. Subparser names will be stored in 'subparser'
    subparsers = parser.add_subparsers(dest='subparser')
    # Note: actual subparsers must be added externally before calling this function.
    try:
        known, unknown = parser.parse_known_args(unparsed_arguments)
    except SystemExit as exc:  # argparse throws SystemExit on error
        raise ValueError('Argument parsing failed') from exc

    # Store unknown args under a dedicated attribute for reference
    if unknown:
        setattr(known, 'unknown', unknown)

    # Determine key for the resulting mapping.
    key = getattr(known, 'subparser', None)
    if key:
        return {key: known}
    else:
        return {'global': known}

