def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    This function looks for placeholders in the form ``{key}`` or ``:key`` within the
    URL string and replaces them with the corresponding values from ``url_args``.
    Placeholders that do not have a mapping entry are left unchanged.

    Args:
        url (str): The URL string containing placeholders.
        url_args (Mapping[str, Any] | None): A mapping of placeholder names to
            replacement values.

    Returns:
        str: The URL with placeholders substituted.

    Examples:
        >>> _replace_url_args('https://api.example.com/users/{id}/details', {'id': 42})
        'https://api.example.com/users/42/details'
        >>> _replace_url_args('https://api.example.com/items/:item_id', {'item_id': 'xyz'})
        'https://api.example.com/items/xyz'
    """
    # Validation and early return
    if not isinstance(url, str):
        return url
    if not isinstance(url_args, (dict, Mapping, None)):
        return url
    if not url_args:
        return url

    import re
    pattern = re.compile(r'\{(\w+)\}|:([A-Za-z0-9_]+)')

    def repl(match: re.Match) -> str:
        key = match.group(1) or match.group(2)
        if key in url_args:
            val = url_args[key]
            # Convert to string, handling bytes explicitly
            if isinstance(val, bytes):
                try:
                    val = val.decode('utf-8')
                except Exception:
                    val = val.decode('utf-8', errors='replace')
            return str(val)
        return match.group(0)

    try:
        return pattern.sub(repl, url)
    except re.error:
        # If regex operation fails for any reason, return original URL
        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    Args:
      url (str): URL containing placeholders such as {placeholder}.
      url_args (Mapping[str, Any]): Mapping of placeholder names to values.

    Returns:
      str: URL with placeholders replaced by corresponding values. Placeholders
           that have no matching key in url_args are left unchanged.
    """
    if not url:
        return ''

    # Ensure url_args is a mapping like dict
    try:
        from collections.abc import Mapping
    except ImportError:
        from typing import Mapping  # type fallback

    if not isinstance(url_args, Mapping):
        raise TypeError('url_args must be a mapping type such as dict')

    import re

    def _replace(match: re.Match) -> str:
        key = match.group(1)
        if key in url_args:
            # Convert value to string and escape characters that may interfere with URL
            # Using urllib.parse.quote to percent-encode non-safe characters.
            try:
                import urllib.parse as _urllib
                return _urllib.quote(str(url_args[key]), safe='')
            except Exception:
                # Fallback to plain string if quoting fails
                return str(url_args[key])
        return match.group(0)  # leave unchanged if key not found

    # Replace placeholders like {key}
    return re.sub(r'\{([^{}]+)\}', _replace, url)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    # Validate input
    if not isinstance(url, str):
        return url
    if not isinstance(url_args, (dict,)):
        # Try to cast to dict if possible
        try:
            url_args = dict(url_args)
        except Exception:
            return url

    # If no arguments provided, return the original URL
    if not url_args:
        return url

    # Replace each placeholder with its corresponding value
    for key, val in url_args.items():
        # Build the placeholder (e.g., `{param}`)
        placeholder = f'{{{key}}}'
        # Convert the value to a string (handle None)
        replacement = '' if val is None else str(val)
        url = url.replace(placeholder, replacement)

    return url

