def get_repo_archive(url: str, destination_path: Path) -> Path:
    """
    Given an url and a destination path, retrieve and extract .tar.gz archive
    which contains 'desc' file for each package.
    Each .tar.gz archive corresponds to an Arch Linux repo ('core', 'extra', 'community').

    Args:
        url: url of the .tar.gz archive to download
        destination_path: the path on disk where to extract archive

    Returns:
        a directory Path where the archive has been extracted to.
    """
    # Validate inputs
    if not isinstance(url, str):
        raise TypeError(f"url must be a str, got {type(url)}")
    if not isinstance(destination_path, Path):
        raise TypeError(f"destination_path must be a pathlib.Path, got {type(destination_path)}")

    # Ensure the parent directory exists
    try:
        destination_path.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        raise OSError(f"Could not create destination directory '{destination_path}': {e}") from e

    # If destination_path exists but is not a directory, raise
    if destination_path.exists() and not destination_path.is_dir():
        raise OSError(f"Destination path '{destination_path}' exists and is not a directory.")

    # Check if destination is empty; if not empty, raise to avoid overwriting
    try:
        if any(destination_path.iterdir()):
            raise OSError(f"Destination directory '{destination_path}' is not empty. Refusing to overwrite.")
    except OSError:
        # raised due to errors other than noSuchDirectory (which shouldn't happen here)
        raise

    # Download the archive to a temporary file
    import tempfile
    import tarfile
    import shutil
    tmp_file = None
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".tar.gz") as tmp:
            tmp_file = Path(tmp.name)
            try:
                with requests.get(url, stream=True, timeout=30) as resp:
                    resp.raise_for_status()
                    for chunk in resp.iter_content(chunk_size=8192):
                        if chunk:
                            tmp.write(chunk)
            except requests.exceptions.RequestException as rev:
                raise RuntimeError(f"Failed to download archive from '{url}': {rev}") from rev

        # Extract the archive
        try:
            with tarfile.open(tmp_file, mode="r:gz") as tar:
                tar.extractall(path=destination_path)
        except tarfile.TarError as te:
            raise RuntimeError(f"Failed to extract tar.gz archive '{tmp_file}': {te}") from te

    finally:
        # Clean up temporary file
        if tmp_file and tmp_file.exists():
            try:
                tmp_file.unlink()
            except OSError:
                pass

    return destination_path

