def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str) or len(name) < 2:
        return name
    first, last = name[0], name[-1]
    if first == last and first in ('"', "'"):
        inner = name[1:-1]
        # Unescape escaped quotes and backslashes
        if first == '"':
            inner = inner.replace(r'\"', '"').replace(r'\\', '\\')
        else:
            inner = inner.replace(r"\'", "'").replace(r'\\', '\\')
        return inner
    return name

def unquote(name):
    """
    Remove quote from the given name.
    """
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Remove matching outer quotes if the same character is at both ends
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ('"', "'", "`"):
        return name[1:-1]
    # If the outer quotes do not match, strip all standard quote characters
    return re.sub(r"[\"'`]", "", name)

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    if len(name) < 2:
        return name
    # Match a quote at the start and the same quote at the end
    match = re.match(r"^(?P<q>['\"])(?P<content>.*)(?P=q)$", name)
    if match:
