    if not isinstance(s, str):
        raise TypeError(f"Expected string input, got {type(s)!r}")

    # Resolve platform
    if platform == 'this':
        platform = 'posix' if os.name == 'posix' else 'win'
    elif platform == 1 or platform == 'posix':
        platform = 'posix'
    elif platform == 0 or platform == 'win':
