def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str):
        # Handle "always" case-insensitively
        if frequency.strip().lower() == "always":
            return None
    else:
        raise ValueError("frequency must be a string or None")

    # Ensure we have a string
    freq_str = str(frequency).strip()

    # Expect exactly two components: a number and a unit
    parts = freq_str.split()
    if len(parts) != 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    num_str, unit = parts
    # Convert number part to int; reject floats or non-numeric
    try:
        value = int(num_str)
    except ValueError:
        raise ValueError(f"Frequency numeric value invalid: '{num_str}'")

    # Normalise unit: lower case, remove trailing 's' if plural
    unit = unit.lower()
    if unit.endswith('s'):
        unit = unit[:-1]

    # Map unit to timedelta keyword
    unit_map = {
        'day': 'days',
        'week': 'weeks',
        'hour': 'hours',
        'minute': 'minutes',
        'second': 'seconds',
        'millisecond': 'milliseconds',
        'microsecond': 'microseconds',
    }

    if unit not in unit_map:
        raise ValueError(f"Unsupported unit in frequency: '{unit}'")

    kwargs = {unit_map[unit]: value}
    return datetime.timedelta(**kwargs)

