def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all
    path fragments into glob patterns. Pass through existing patterns untouched.
    """
    if find_paths is None:
        raise ValueError("find_paths cannot be None")

    transformed = []
    for frag in find_paths:
        if not isinstance(frag, str):
            raise TypeError(f"Each find_paths element must be a string, got {type(frag)}")

        # If the string contains a scheme delimiter (':'), treat it as a pattern and leave it unchanged.
        if ':' in frag:
            transformed.append(frag)
        else:
            # Wrap the fragment in a shell search pattern that matches any file containing the fragment.
            # Escape backslashes and quotes to avoid shell globbing issues.
            safe_frag = frag.replace('\\', '\\\\').replace('"', '\\"')
            transformed.append(f'sh:**/*{safe_frag}*/**')
    return transformed

