def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Only Windows OS can run Git Bash
        if os.name != 'nt':
            return False

        # Git Bash typically sets OSTYPE to 'msys'
        if os.environ.get('OSTYPE', '').startswith('msys'):
            return True

        # Git Bash also sets MSYSTEM to something like 'MINGW64_NT-10.0.19041'
        if os.environ.get('MSYSTEM', '').startswith('MINGW'):
            return True

        return False
    except Exception:
        # In case of any unexpected environment, conservatively assume not Git Bash
        return False

