def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    """
    Given a target config filename and rendered config YAML, write it out to file.
    Create any containing directories as needed. But if the file already exists and
    overwrite is False, abort before writing anything.
    """
    if not config_filename or not isinstance(config_filename, str):
        raise ValueError("config_filename must be a non-empty string")
    # Expand user (~) and convert to absolute path
    config_path = os.path.expanduser(config_filename)
    if os.path.isfile(config_path) and not overwrite:
        # Do nothing if file exists and overwrite not requested
        return
    # Ensure the containing directory exists
    dir_name = os.path.dirname(config_path) or "."
    try:
        os.makedirs(dir_name, exist_ok=True)
    except OSError as exc:
        # If the directory still does not exist, raise
        if not os.path.isdir(dir_name):
            raise
    # Write the file
    try:
        with open(config_path, "w") as f:
            if isinstance(rendered_config, str):
                f.write(rendered_config)
            else:
                # Assume rendered_config is a Python object to dump as YAML
                yaml.dump(rendered_config, f, Dumper=yaml.RoundTripDumper, width=float("inf"))
        # Set file permissions
        try:
            os.chmod(config_path, mode)
        except (TypeError, OSError):
            # Ignore if mode cannot be applied (e.g., on Windows)
            pass
    except OSError as exc:
        raise OSError(f"Failed to write configuration to {config_path}: {exc}") from exc
    return config_path

