def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    if matcher is None:
        raise TypeError("matcher must not be None")

    # Extract the variable name.
    try:
        var_name = matcher.group(1)
    except AttributeError:
        try:
            var_name = matcher[0]
        except Exception as exc:
            raise TypeError("matcher must provide a variable name") from exc

    # Extract the default value if present.
    var_default = None
    try:
        # If the matcher provides a .group method, use it.
        var_default = matcher.group(2)
    except AttributeError:
        # Fallback to sequence indexing if available.
        try:
            var_default = matcher[1] if len(matcher) > 1 else None
        except Exception:
            var_default = None

    # Look up the environment variable.
    value = os.environ.get(var_name)

    if value is None:
        if var_default is not None:
            return var_default
        raise KeyError(f'Environment variable "{var_name}" not found and no default value provided')

    return value

