def get_pattern(pattern, strip=True):
    """Convert a string to a compiled regular expression pattern.

    If the input `pattern` is a string, it will be compiled using `re.compile`.  
    If it is already a compiled pattern (`re.Pattern` / `_sre.SRE_Pattern`), it is returned unchanged.  
    If `strip` is True, leading/trailing whitespace and newline characters are stripped from the string before compilation.

    Raises:
        TypeError: If `pattern` is not ``str`` or a compiled regular expression.
        ValueError: If the provided string is not a valid regular expression.
    """
    import re

    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as exc:
            raise ValueError(f"Invalid regular expression: {pattern!r}") from exc

    # Determine the compiled pattern type depending on the Python version
    if hasattr(re, "Pattern"):
        PatternType = re.Pattern
    else:  # pragma: no cover
        import _sre
        PatternType = _sre.SRE_Pattern

    if isinstance(pattern, PatternType):
        return pattern

    raise TypeError(
        f"pattern must be a string or compiled regular expression, got {type(pattern).__name__}"
    )

