def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Build mapping from subject to its parents
    parent_map: Dict["Node", Set["Node"]] = {}
    subjects: Set["Node"] = set()
    objects: Set["Node"] = set()

    try:
        for s, p, o in graph.triples((None, prop, None)):
            # Only consider triples with the requested property
            if p != prop:
                continue
            parent_map.setdefault(s, set()).add(o)
            subjects.add(s)
            objects.add(o)
    except Exception as exc:
        raise ValueError(f"Failed to iterate over graph triples: {exc}") from exc

    def _collect_roots(start_nodes: Iterable["Node"]) -> Set["Node"]:
        """Traverse upward from start_nodes and collect nodes with no parents."""
        stack = list(start_nodes)
        seen = set()
        found_roots: Set["Node"] = set()
        while stack:
            node = stack.pop()
            if node in seen:
                continue
            seen.add(node)
            node_parents = parent_map.get(node)
            if not node_parents:
                found_roots.add(node)
            else:
                stack.extend(node_parents)
        return found_roots

    # If roots not provided, return all nodes that appear as an object but never as a subject
    if roots is None:
        return objects - subjects

    # Ensure roots is an iterable of nodes
    if isinstance(roots, set):
        start = roots
    else:
        start = {roots}
    return _collect_roots(start)

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader

    """
    # Start with an empty set if no initial roots are provided
    if roots is None:
        roots = set()
    else:
        roots = set(roots)

    # Collect all subjects (children) and objects (parents) for the given prop
    all_nodes: Set["Node"] = set()
    parent_nodes: Set["Node"] = set()

    try:
        for child, _, parent in graph.triples((None, prop, None)):
            all_nodes.update((child, parent))
            parent_nodes.add(parent)
    except Exception:
        # If the graph interface is not compatible, fail gracefully
        return roots

    # Nodes that never appear as a parent are roots
    for node in all_nodes:
        if node not in parent_nodes:
            roots.add(node)

    return roots

