def make_array(shape, dtype=np.dtype("float32")):
    """Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize dtype
    try:
        dtype = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"Invalid dtype: {dtype}") from exc

    # Normalize shape
    if isinstance(shape, int):
        shape_tuple = (shape,)
    elif isinstance(shape, (tuple, list)):
        try:
            shape_tuple = tuple(int(d) for d in shape)
        except Exception as exc:
            raise ValueError("All elements of shape must be integers") from exc
    else:
        try:
            shape_tuple = tuple(shape)
        except Exception as exc:
            raise TypeError("Shape must be an int, tuple, or list of ints") from exc

    # Check for negative dimensions
    for dim in shape_tuple:
        if dim < 0:
            raise ValueError(f"Negative dimension {dim} in shape {shape_tuple}")

    # Create the array
    try:
        return np.empty(shape_tuple, dtype=dtype)
    except Exception as exc:
        raise ValueError(f"Could not create array with shape {shape_tuple} and dtype {dtype}") from exc

