def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise TypeError("seq cannot be None")
    # Known sequence types that we can return unchanged
    if isinstance(seq, (list, tuple, str, bytes, bytearray)):
        return seq, type(seq).__name__
    # Handle file-like objects that provide a read method
    if hasattr(seq, "read") and callable(seq.read):
        try:
            data = seq.read(bufsize) if bufsize is not None else seq.read()
            # if the read returns a bytes-like, we return it as is
            if isinstance(data, (bytes, str)):
                return data, type(data).__name__
        except Exception:
            # fallback to treating as iterable
            pass
