def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale requested
    if other is None:
        # If the graph does not store a scale attribute, raise an informative error
        try:
            current_scale = self.scale
        except AttributeError:
            raise ValueError(
                "Graph does not expose a 'scale' attribute; cannot retrieve current scale."
            )
        return current_scale

    # Validate that the provided scale is numeric
    if not isinstance(other, (int, float)):
        raise TypeError(
            f"Scale value must be numeric (got {type(other).__name__})."
        )

    # Ensure we have a known, non‑zero current scale
    try:
        current_scale = self.scale
    except AttributeError:
        raise ValueError(
            "Graph does not expose a 'scale' attribute; cannot rescale."
        )
    if current_scale is None or current_scale == 0:
        raise ValueError(
            "Cannot rescale graph with unknown or zero current scale."
        )

    # Identify the last coordinate field to rescale
    try:
        fields = self.fields
    except AttributeError:
        raise ValueError(
            "Graph does not expose a 'fields' attribute; cannot determine coordinate to rescale."
        )
    if not fields:
        raise ValueError("Graph has no coordinate fields to rescale.")
    last_field = fields[-1]

    # Retrieve the data arrays; raise informative errors if missing
    try:
        data_array = getattr(self, "_data")[last_field]
    except (AttributeError, KeyError, TypeError):
        raise ValueError(
            f"Data for the coordinate field '{last_field}' not found; cannot rescale."
        )

    # Apply the scaling transformation
    try:
        factor = float(other) / float(current_scale)
    except Exception as exc:
        raise ValueError(f"Failed to compute scaling factor: {exc}") from exc

    # Perform the in‑place scaling of the coordinate values
    try:
        getattr(self, "_data")[last_field] = data_array * factor
    except Exception as exc:
        raise ValueError(
            f"Failed to scale data for field '{last_field}': {exc}"
        ) from exc

    # If an error array exists for this coordinate, scale it as well
    errors = getattr(self, "_errors", {})
    if isinstance(errors, dict) and last_field in errors:
        try:
            getattr(self, "_errors")[last_field] = errors[last_field] * factor
        except Exception as exc:
            raise ValueError(
                f"Failed to scale errors for field '{last_field}': {exc}"
            ) from exc

    # Update the graph’s stored scale
    self.scale = other

    return self

