def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    from zope.interface import Invalid

    errors = []

    # 1. Check providedBy unless tentative
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise ValueError()
        except Exception:
            errors.append(
                f"candidate {candidate!r} does not claim to provide {iface!r}"
            )

    # Helper to compare signatures
    def _signatures_match(interface_sig, candidate_sig):
        # Quick check: same number of parameters
        if len(interface_sig.parameters) != len(candidate_sig.parameters):
            return False
        # Compare each parameter by name and kind
        for i, (iname, iparam) in enumerate(interface_sig.parameters.items()):
            cname, cparam = list(candidate_sig.parameters.items())[i]
            if iname != cname:
                return False
            if iparam.kind != cparam.kind:
                return False
            # Compare default values if present
            if iparam.default is not inspect.Parameter.empty:
                if cparam.default is inspect.Parameter.empty:
                    return False
                if iparam.default != cparam.default:
                    return False
            else:
                if cparam.default is not inspect.Parameter.empty:
                    return False
        return True

    # 2. Methods
    # Interface methods are stored in iface._methods and are descriptors
    for name, iface_method in getattr(iface, "_methods", {}).items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue
        candidate_method = getattr(candidate, name)
        if not callable(candidate_method):
            errors.append(f"Attribute '{name}' is not callable")
            continue
        # Get signatures
        iface_sig = getattr(iface_method, "__signature__", None)
        if iface_sig is None:
            # Try to fetch signature via inspect (fallback)
            try:
                iface_sig = inspect.signature(iface_method)
            except Exception:
                iface_sig = None
        try:
            candidate_sig = inspect.signature(candidate_method)
        except Exception:
            candidate_sig = None
        if iface_sig is not None and candidate_sig is not None:
            if not _signatures_match(iface_sig, candidate_sig):
                errors.append(
                    f"Method '{name}' signature mismatch: "
                    f"expected {iface_sig} got {candidate_sig}"
                )
        # else skip signature check if unable

    # 3. Attributes
    for name, iface_attr in getattr(iface, "_attributes", {}).items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required attribute '{name}'")
            continue
        # Optionally, could check type if iface_attr is a type/typing
        # but interface attributes are not type annotated by default.
        # So skip further checks.

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

