def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__."""
    # Normalize bases to a tuple; raise if empty
    if not bases:
        # No bases: default to 'type', but honour explicit_mc if provided
        return explicit_mc if explicit_mc is not None else type

    # Helper to get the metaclass of a base
    def _get_meta(b):
        try:
            return type(b)
        except Exception:
            # Fallback for old‑style or non‑class objects
            return b.__class__

    # Compute the candidate metaclass from the bases
    metaclasses = [_get_meta(b) for b in bases]

    def _find_most_derived(mcs):
        """
        Find the most derived metaclass among a list of metaclasses.
        Raises TypeError if there is a conflict (i.e., neither is a
        subclass of the other).
        """
        if not mcs:
            return type
        derived = mcs[0]
        for mc in mcs[1:]:
            if issubclass(mc, derived):
                derived = mc
            elif not issubclass(derived, mc):
                raise TypeError(
                    f"metaclass conflict: {mc!r} is not a subclass of {derived!r}"
                )
        return derived

    try:
        candidate_meta = _find_most_derived(metaclasses)
    except TypeError as e:
        # Propagate the conflict error
        raise e

    # If an explicit metaclass was supplied, ensure compatibility
    if explicit_mc is not None:
        try:
            # In CPython, the explicit metaclass must be a subclass of every
            # candidate metaclass, or vice versa.
            # Here we simply check if it is subclass of the chosen candidate.
            # This mirrors Python 3's behavior.
            if not issubclass(explicit_mc, candidate_meta):
                if not issubclass(candidate_meta, explicit_mc):
                    raise TypeError(
                        f"metaclass conflict: {explicit_mc!r} is incompatible "
                        f"with base metaclasses which would use {candidate_meta!r}"
                    )
                # candidate_meta is a subclass of explicit_mc, so use explicit_mc
                candidate_meta = explicit_mc
        except TypeError as exc:
            # If explicit_mc is not a class or cannot be subclassed, raise
            raise TypeError(f"invalid explicit metaclass: {explicit_mc!r}") from exc

    return candidate_meta

