    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    # Accept a full ElementTree as input by getting its root
    if hasattr(node, "getroot") and callable(node.getroot):
        try:
            node = node.getroot()
        except Exception:
            raise TypeError("Unable to retrieve root from ElementTree object")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError("node must be an ElementTree Element or ElementTree") from exc

    result = {}
    for child in children:
        tag = child.tag
        # Preserve duplicates as list, otherwise single element
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

