def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate the base URL
    if not isinstance(url, str) or not url:
        raise ValueError("url must be a non-empty string")
    # Ensure a scheme is present
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("url must include a scheme (http:// or https://)")
    # Remove any trailing slash for consistency
    base = url.rstrip("/")
    # Determine the href for the nodeinfo document
    if document_path is None:
        href = f"{base}/.well-known/nodeinfo/1.0"
    else:
        # Normalize the custom path
        custom_path = document_path
        if not custom_path.startswith("/"):
            custom_path = "/" + custom_path
        href = f"{base}{custom_path}"
    # Construct the .well-known NodeInfo document
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/spec#nodeinfo",
                "href": href,
            }
        ]
    }

