def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # lxml is required for xmlsec
        from lxml import etree
    except Exception:
        # If lxml is not available, fail gracefully
        return False

    # Parse the signed XML document
    try:
        if isinstance(doc, bytes):
            xml_doc = etree.fromstring(doc)
        else:
            xml_doc = etree.fromstring(doc.encode('utf-8'))
    except Exception:
        return False

    # Ensure there is a Signature element in the document.
    # If not, try to add it from the provided signature string.
    if xml_doc.find('.//{http://www.w3.org/2000/09/xmldsig#}Signature') is None:
        if signature:
            try:
                if isinstance(signature, bytes):
                    sig_elem = etree.fromstring(signature)
                else:
                    sig_elem = etree.fromstring(signature.encode('utf-8'))
                xml_doc.append(sig_elem)
            except Exception:
                # Cannot append signature, verification cannot proceed
                return False

    # Perform signature verification using xmlsec
    try:
        import xmlsec
    except Exception:
        # xmlsec not available
        return False

    try:
        # Load the public key either from PEM string or file path
        try:
            key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        except Exception:
            key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM, None)

        ctx = xmlsec.SignatureContext()
        ctx.key = key

        # Register common ID attributes so that references can be resolved
        for el in xml_doc.iter():
            for id_attr in ("ID", "Id", "id"):
                if id_attr in el.attrib:
                    el.set(id_attr, el.get(id_attr))
                    xmlsec.tree.register_id(el, id_attr)

        # Verify the signature; this will raise an exception on failure
        ctx.verify(xml_doc)
        return True
    except Exception

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from lxml import etree
        import xmlsec
    except ImportError as exc:
        raise RuntimeError(
            "The lxml and xmlsec libraries are required for signature verification"
        ) from exc

    # Parse the XML document
    try:
        root = etree.fromstring(doc.encode("utf-8"))
    except Exception as exc:
        return False

    # Locate the Signature node in the XML
    sig_node = xmlsec.tree.find_node(root, xmlsec.constants.NodeSignature)
    if sig_node is None:
        return False

    # Optional consistency check: make sure the provided signature string matches
    # the SignatureValue inside the XML (base64 encoded)
    sig_value_nodes = sig_node.findall(".//{http://www.w3.org/2000/09/xmldsig#}SignatureValue")
    if sig_value_nodes:
        xml_sig_value = sig_value_nodes[0].text.strip() if sig_value_nodes[0].text else ""
        if xml_sig_value != signature:
            return False

    # Create a signature context and load the public key
    try:
        key = xmlsec.Key.from_memory(public_key.encode("utf-8"),
                                     xmlsec.constants.KeyDataFormatPem,
                                     None)
    except Exception as exc:
        return False

    ctx = xmlsec.SignatureContext()
    ctx.key = key

    # Perform the verification
    try:
        ctx.verify(sig_node)
        return True
