    """
    # Basic validation of the handle
    if not handle or '@' not in handle:
        return None

    # Split handle into local part and host
    try:
        local_part, host = handle.split('@', 1)
    except ValueError:
        return None

    if not host:
        return None

    # Prepare the query part, ensuring proper percent‑encoding
    try:
        from urllib.parse import quote
        encoded_handle = quote(handle, safe='')
    except Exception:
        encoded_handle = handle

    # Attempt HTTPS first, then fallback to HTTP
    for scheme in ('https', 'http'):
        url = f"{scheme}://{host}/.well-known/webfinger?resource=acct:{encoded_handle}"
        try:
