            with urlopen(url, timeout=5) as response:
                # Read and decode the response
                body = response.read()
                try:
                    return body.decode('utf-8')
                except Exception:
                    # Return raw bytes as string if decoding fails
                    return body.decode(errors='replace')
        except Exception:
            continue

    # All attempts failed
    return None

