def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    method = method.lower()
    if method not in {"get", "post", "put", "delete", "patch", "head"}:
        raise ValueError(f"Unsupported HTTP method: {method!r}")

    # Build the arguments for the request
    request_kwargs = {"url": url, "timeout": timeout}
    if method == "post":
        request_kwargs["data"] = data
    else:
        request_kwargs["params"] = data if isinstance(data, dict) else {}

    # Merge any extra keyword arguments
    request_kwargs.update(kwargs)

    try:
        request_func = getattr(requests, method)
    except AttributeError:
        raise ValueError(f"Requests library does not support method: {method!r}")

    try:
        response = request_func(*args, **request_kwargs)
        return response.status_code, None
    except requests.RequestException as e:
        return None, e
    except Exception as e:
        # Catch any unexpected exception and return it as the error part
        return None, e

