def dict_insert(dic, val, key, *keys):
    """
    insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dict")
    # build full key path
    path = []
    if isinstance(key, (list, tuple)):
        for k in key:
            if not isinstance(k, str):
                raise ValueError("All keys must be strings")
            path.append(k)
    else:
        if not isinstance(key, str):
            raise ValueError("Key must be a string or list/tuple of strings")
        path.append(key)
    for k in keys:
        if not isinstance(k, str):
            raise ValueError("All keys must be strings")
        path.append(k)
    if not path:
        raise ValueError("At least one key must be provided")
    current = dic
    for k in path[:-1]:
        if k not in current or not isinstance(current[k], dict):
            current[k] = {}
        current = current[k]
    current[path[-1]] = val
    return dic

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")

    # Build the full key chain
    full_keys = [key] + list(keys)

    if not full_keys:
        return dic  # nothing to insert

    current = dic
    # Iterate through all keys except the last to create nested dicts
    for k in full_keys[:-1]:
        try:
            nxt = current[k]
            if not isinstance(nxt, dict):
                # If the existing value is not a dict, replace it with a new dict
                current[k] = {}
                nxt = current[k]
        except KeyError:
            current[k] = {}
            nxt = current[k]
        except TypeError:
            # Current is not subscriptable; replace with dict
            current[k] = {}
            nxt = current[k]
        current = nxt

    # Set the final value
    last_key = full_keys[-1]
    try:
        current[last_key] = val
    except TypeError:
        # Current is not subscriptable; cannot assign value
        raise TypeError(f"Cannot assign to key '{last_key}' because intermediate path is not a dict")

    return dic

