def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Start with defaults derived from the scheme (or args)
    defaults = {}
    if hasattr(self, 'build_defaults') and callable(self.build_defaults):
        try:
            defaults = self.build_defaults() or {}
        except Exception:
            defaults = {}

    # Fetch values from the spec.  The spec might expose a `defaults`
    # attribute, behave like a dict, or provide a `get` method.  Any key
    # found in the spec overrides the base default.
    spec_vals = {}
    spec = getattr(self, 'spec', None)
    if spec is not None:
        try:
            if hasattr(spec, 'defaults') and isinstance(spec.defaults, dict):
                spec_vals = spec.defaults
            elif isinstance(spec, dict):
                spec_vals = spec
            elif hasattr(spec, 'get') and callable(spec.get):
                # enumerate over the known defaults and additionally
                # collect any extra keys that spec may provide
                for key in defaults:
                    val = spec.get(key, None)
                    if val is not None:
                        spec_vals[key] = val
                # try to pull any additional keys via dir()
                for attr in dir(spec):
                    if not attr.startswith('_') and not callable(getattr(spec, attr)):
                        spec_vals[attr] = getattr(spec, attr)
            else:
                # fall back to inspecting attributes directly
                for key in defaults:
                    if hasattr(spec, key):
                        spec_vals[key] = getattr(spec, key)
        except Exception:
            spec_vals = {}

    # Merge defaults: spec values take precedence
    resolved = dict(defaults)
    resolved.update(spec_vals)

    return resolved

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    The method gathers default values defined in the command specification
    (`self.spec` if available) and falls back to inspecting `self.args`
    directly when a spec is not present or does not provide defaults.
    Nested options that contain sub‑schemes (e.g. dict options with a
    nested scheme) are handled recursively – if the nested scheme
    implements a ``build_defaults`` method it is used, otherwise the
    defaults of its arguments are collected manually.

    Returns:
