        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Ensure args is a mapping; if a Namespace object, convert to dict
    if args is None:
        raise ValueError("args must not be None")
    if not isinstance(args, dict):
        try:
            args = vars(args)
        except Exception:
            raise TypeError("args must be a mapping or dict-like object")

    # Determine control arguments.  If the instance defines a
    # ``CONTROL_KEYS`` attribute, use it; otherwise fall back to an
    # empty set so that all keys are treated as nested arguments.
    control_keys = set()
    if hasattr(self, "CONTROL_KEYS"):
        control_keys = set(getattr(self, "CONTROL_KEYS"))
    elif hasattr(self, "_control_keys"):
        control_keys = set(getattr(self, "_control_keys"))

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        # Skip private or special attributes that shouldn't be processed
        if key.startswith("_"):
            continue
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

