                    return val.strip().lower() in ("true", "1", "yes", "y", "on")
                return bool(val)
            if target_type is list:
                if isinstance(val, str):
                    # split by comma or space, ignore empty parts
                    return [v.strip() for v in val.replace(",", " ").split() if v.strip()]
                if isinstance(val, (tuple, set)):
                    return list(val)
                return [val]
            # For numeric types (int, float, etc.), convert directly
            return target_type(val)
        except (ValueError, TypeError):
            # If conversion fails, fallback to original value
            return val

    # Iterate over provided arguments and cast if metadata exists
    for key in list(values_dict.keys()):
        meta = parser_def.get(key)
        if meta is None:
            # No definition available; keep as is
            continue

        # Determine the expected type
        if isinstance(meta, dict):
            target_type = meta.get("type", str)
        else:
            target_type = meta

        # Convert and update in place
        values_dict[key] = _convert_value(values_dict[key], target_type)

    return values_dict

