    Casts arguments to correct types by modifying values_dict param.
    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified values_dict with converted types
    """
    # Retrieve argument metadata for the specified parser
    # Expected format:
    #   self._arg_definitions = {
    #       "parser_name": {
    #           "arg_name": {"type": int, "default": 0},
    #           "other_arg": {"type": bool, "default": False},
    #           ...
    #       },
    #       ...
    #   }
    # or simpler: {"arg_name": int, ...}
    arg_defs = getattr(self, "_arg_definitions", {})
    parser_def = arg_defs.get(parser_name, {})

    # Helper to convert a single value based on a target type
    def _convert_value(val, target_type):
        if isinstance(val, target_type):
            return val
        try:
            if target_type is bool:
                if isinstance(val, str):
                    return val.strip().lower() in ("true", "1", "yes", "y", "on")
                return bool(val)
            if target_type is list:
                if isinstance(val, str):
                    # split by comma or space, ignore empty parts
                    return [v.strip() for v in val.replace(",", " ").split() if v.strip()]
                if isinstance(val, (tuple, set)):
                    return list(val)
                return [val]
            # For numeric types (int, float, etc.), convert directly
            return target_type(val)
        except (ValueError, TypeError):
            # If conversion fails, fallback to original value
            return val

    # Iterate over provided arguments and cast if metadata exists
    for key in list(values_dict.keys()):
        meta = parser_def.get(key)
        if meta is None:
            # No definition available; keep as is
            continue

        # Determine the expected type
        if isinstance(meta, dict):
            target_type = meta.get("type", str)
        else:
            target_type = meta

        # Convert and update in place
        values_dict[key] = _convert_value(values_dict[key], target_type)

    return values_dict

